<!DOCTYPE html>
<html>
<head>
  <title>Bouncing Ball Playground</title>
  <style>
    body {
      background-color: #1e1e1e;
      color: #f0f0f0;
      font-family: sans-serif;
      margin: 0;
      overflow: hidden; /* Hide scrollbars */
    }

    #sim {
      background-color: #282828;
      border: none;
      display: block; /* Ensure it takes up full width */
    }

    button {
      background-color: #3e3e3e;
      color: #f0f0f0;
      border: none;
      padding: 10px 20px;
      font-size: 16px;
      cursor: pointer;
      margin: 10px;
    }

    button:hover {
      background-color: #4e4e4e;
    }
  </style>
</head>
<body>
  <canvas id="sim"></canvas>
  <button id="drop">Drop Ball</button>
  <button id="play">Play</button>
  <button id="clear">Clear</button>

  <script>
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d');
    const w = canvas.width = 800;
    const h = canvas.height = 600;

    window.sim = {
      w,
      h,
      balls: [],
      addBall(x, y, vx=0, vy=0, r=10) {
        this.balls.push({ x, y, vx, vy, r });
      },
      clear() {
        this.balls = [];
      },
      step(dt=1) {
        for (const ball of this.balls) {
          ball.vy += dt * 9.81; // Gravity

          // Bounce off floor
          if (ball.y + ball.r > h) {
            ball.y = h - ball.r;
            ball.vy *= 0.7; // Restitution (energy loss)
          }

          // Bounce off walls
          if (ball.x < ball.r || ball.x + ball.r > w) {
            ball.x = ball.r > w - ball.r ? w - ball.r : ball.r;
            ball.vx *= -1;
          }
          if (ball.y < ball.r) {
            ball.y = ball.r;
            ball.vy *= -1;
          }
        }

        // Redraw
        ctx.clearRect(0, 0, w, h);
        for (const ball of this.balls) {
          ctx.beginPath();
          ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
          ctx.fillStyle = '#ff6666'; // Orange color
          ctx.fill();
          ctx.closePath();
        }
      },
    };

    let playing = false;
    document.addEventListener('click', (e) => {
      const x = e.clientX - w / 2;
      const y = e.clientY - h / 2;
      sim.addBall(x, y);
    });

    document.getElementById('play').addEventListener('click', () => {
      playing = true;
      let lastTime = performance.now();
      function gameLoop() {
        const dt = (performance.now() - lastTime) / 1000;
        sim.step(dt);
        lastTime = performance.now();

        if (playing) {
          requestAnimationFrame(gameLoop);
        }
      }
      gameLoop();
    });

    document.getElementById('clear').addEventListener('click', () => {
      sim.clear();
    });
  </script>
</body>
</html>
